insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('scenes-nodes', 1, 1, 'scene', '{"key":"scenes-nodes","version":1,"module":1,"kind":"scene","godotVersion":"4.6","title":{"id":"Scene dan node","en":"Scenes and nodes"},"summary":{"id":"Susun pohon node kecil dan lihat bagaimana posisi anak mengikuti induknya.","en":"Arrange a small node tree and see how a child''s position follows its parent."},"minutes":{"explain":8,"practice":15},"objective":{"id":"Menjelaskan hubungan induk-anak node dan perbedaan posisi lokal dan global.","en":"Explain parent-child node relationships and the difference between local and global position."},"whyGodot":{"id":"Setiap game Godot dibangun dari node yang disusun menjadi scene. Pemain, musuh, dan HUD semuanya scene.","en":"Every Godot game is built from nodes arranged into scenes. The player, enemies, and HUD are all scenes."},"explanation":[{"type":"p","text":{"id":"Node adalah blok bangunan terkecil di Godot. Setiap node punya tugas: `Sprite2D` menampilkan gambar, `CollisionShape2D` memberi bentuk tabrakan, `CharacterBody2D` bergerak dan bertabrakan.","en":"A node is Godot''s smallest building block. Each node has a job: `Sprite2D` shows an image, `CollisionShape2D` provides a collision shape, `CharacterBody2D` moves and collides."}},{"type":"p","text":{"id":"Node disusun sebagai pohon. Satu pohon yang disimpan disebut scene. Scene bisa di-instance (dipakai ulang) di dalam scene lain, misalnya scene Player di dalam scene Level.","en":"Nodes are arranged as a tree. A saved tree is called a scene. A scene can be instanced (reused) inside another scene, for example a Player scene inside a Level scene."}},{"type":"list","items":[{"id":"`position` adalah posisi lokal: relatif terhadap induk.","en":"`position` is the local position: relative to the parent."},{"id":"`global_position` adalah posisi di dunia: posisi induk ditambah posisi lokal (untuk kasus tanpa rotasi/skala).","en":"`global_position` is the world position: the parent''s position plus the local position (when there is no rotation/scale)."},{"id":"Saat induk bergerak, semua anaknya ikut bergerak.","en":"When a parent moves, all its children move with it."}]}],"workedExample":[{"type":"p","text":{"id":"Main (Node2D) di (40, 30). Player di dalam Main dengan posisi lokal (100, 80). Posisi global Player = (40+100, 30+80) = (140, 110).","en":"Main (Node2D) is at (40, 30). Player is inside Main with local position (100, 80). Player''s global position = (40+100, 30+80) = (140, 110)."}},{"type":"code","code":"Main (Node2D)\n└─ Player (CharacterBody2D)\n   ├─ Sprite2D\n   └─ CollisionShape2D","caption":{"id":"Struktur scene Player yang umum","en":"A common Player scene structure"}}],"activity":{"name":{"id":"Penyusun Scene","en":"Scene Composer"},"instructions":[{"id":"Jadikan Player (CharacterBody2D) anak dari Main.","en":"Make Player (CharacterBody2D) a child of Main."},{"id":"Pastikan Player punya anak Sprite2D dan CollisionShape2D. Tambahkan node jika perlu.","en":"Make sure Player has a Sprite2D and a CollisionShape2D child. Add nodes if needed."},{"id":"Geser Main dan perhatikan posisi global anak-anaknya.","en":"Move Main and watch its children''s global positions."},{"id":"Tulis prediksi posisi global Sprite2D, lalu jalankan pemeriksaan.","en":"Enter your prediction of the Sprite2D global position, then run the checks."}],"hints":[{"id":"Pilih node, lalu pilih induk barunya dari daftar \"Induk\".","en":"Select a node, then choose its new parent from the \"Parent\" list."},{"id":"Posisi global = jumlah posisi lokal node dan semua leluhurnya.","en":"Global position = the sum of the local positions of the node and all its ancestors."}],"initialConfig":{"kind":"scene","v":1,"nodes":[{"id":"n1","type":"Node2D","name":"Main","parent":null,"x":40,"y":30},{"id":"n2","type":"CharacterBody2D","name":"Player","parent":null,"x":100,"y":80},{"id":"n3","type":"Sprite2D","name":"Sprite2D","parent":"n1","x":0,"y":-10}],"prediction":null},"limits":{"maxEntities":10,"maxSeconds":1200}},"checks":["scene.structure","scene.predict_global"],"checkLabels":{"scene.structure":{"id":"Main → Player (CharacterBody2D) → Sprite2D + CollisionShape2D","en":"Main → Player (CharacterBody2D) → Sprite2D + CollisionShape2D"},"scene.predict_global":{"id":"Prediksi posisi global Sprite2D tepat","en":"Sprite2D global position prediction is correct"}},"fidelity":{"teaches":{"id":"Hubungan induk-anak dan posisi lokal versus global.","en":"Parent-child relationships and local versus global position."},"differs":[{"id":"Ini model sebagian. Tidak ada SceneTree lengkap, siklus hidup node, rotasi, skala, atau Inspector.","en":"This is a partial model. There is no full SceneTree, node lifecycle, rotation, scale, or Inspector."},{"id":"Editor Godot asli memakai dock Scene dan Inspector; di sini hanya tombol dan daftar.","en":"The real Godot editor uses the Scene dock and Inspector; here there are only buttons and lists."}]},"misconceptions":[{"id":"Posisi yang tertulis di Inspector selalu posisi di layar. (Salah: itu posisi lokal.)","en":"The position in the Inspector is always the screen position. (Wrong: it is the local position.)"},{"id":"Scene dan node adalah hal yang berbeda sama sekali. (Scene adalah pohon node yang disimpan.)","en":"Scenes and nodes are completely different things. (A scene is a saved tree of nodes.)"}],"quiz":{"prompt":{"id":"Apa yang dicetak kode ini?","en":"What does this code print?"},"code":"# Parent is at (50, 0). This node''s position is (10, 20).\nprint(global_position)","options":[{"id":"(10, 20)","en":"(10, 20)"},{"id":"(60, 20)","en":"(60, 20)"},{"id":"(50, 0)","en":"(50, 0)"}],"answer":1,"explanation":{"id":"Global = induk (50, 0) + lokal (10, 20) = (60, 20).","en":"Global = parent (50, 0) + local (10, 20) = (60, 20)."}},"reflection":{"id":"Mengapa memisahkan Player menjadi scene sendiri berguna saat membuat beberapa level?","en":"Why is it useful to make Player its own scene when building several levels?"},"transfer":{"steps":[{"id":"Buat scene baru dengan root `CharacterBody2D`, beri nama Player.","en":"Create a new scene with a `CharacterBody2D` root named Player."},{"id":"Tambahkan anak `Sprite2D` dan `CollisionShape2D`. Simpan sebagai player.tscn.","en":"Add `Sprite2D` and `CollisionShape2D` children. Save as player.tscn."},{"id":"Buat scene Main (`Node2D`) dan instance player.tscn dengan tombol rantai (Instantiate Child Scene).","en":"Create a Main scene (`Node2D`) and instance player.tscn with the chain button (Instantiate Child Scene)."},{"id":"Ubah posisi Main di Inspector dan amati Player ikut bergerak.","en":"Change Main''s position in the Inspector and watch Player move with it."}],"snippet":null,"question":{"id":"Di Godot, setelah meng-instance Player, apa yang terjadi pada Player saat kamu menggeser Main? Jelaskan dengan istilah posisi lokal dan global.","en":"In Godot, after instancing Player, what happens to Player when you move Main? Explain using local and global position."}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('movement', 1, 2, 'movement', '{"key":"movement","version":1,"module":2,"kind":"movement","godotVersion":"4.6","title":{"id":"Koordinat dan gerakan","en":"Coordinates and movement"},"summary":{"id":"Gerakkan persegi dengan aksi input dan pahami mengapa kecepatan dikalikan delta.","en":"Move a rectangle with input actions and understand why speed is multiplied by delta."},"minutes":{"explain":8,"practice":15},"objective":{"id":"Menggerakkan objek dengan `Vector2`, aksi input, dan kecepatan dalam piksel per detik.","en":"Move an object with `Vector2`, input actions, and speed in pixels per second."},"whyGodot":{"id":"Hampir semua game butuh gerakan yang sama cepatnya di komputer cepat maupun lambat. Delta membuat itu terjadi.","en":"Almost every game needs movement that is equally fast on fast and slow computers. Delta makes that happen."},"explanation":[{"type":"p","text":{"id":"Di Godot 2D, sumbu x ke kanan dan sumbu y ke BAWAH. `Vector2(1, 0)` berarti ke kanan, `Vector2(0, 1)` berarti ke bawah.","en":"In Godot 2D, the x axis points right and the y axis points DOWN. `Vector2(1, 0)` means right, `Vector2(0, 1)` means down."}},{"type":"p","text":{"id":"`_process(delta)` dipanggil setiap frame. `delta` adalah jumlah detik sejak frame sebelumnya, misalnya 0,016 pada 60 FPS atau 0,033 pada 30 FPS.","en":"`_process(delta)` is called every frame. `delta` is the number of seconds since the previous frame, for example 0.016 at 60 FPS or 0.033 at 30 FPS."}},{"type":"p","text":{"id":"Jika speed = 120 piksel/detik, maka `position += direction * speed * delta` memindahkan objek 120 piksel per detik berapa pun FPS-nya.","en":"If speed = 120 pixels/second, `position += direction * speed * delta` moves the object 120 pixels per second at any FPS."}},{"type":"callout","tone":"tip","text":{"id":"Nama aksi seperti \"move_left\" dibuat di Project → Project Settings → Input Map. Kode memakai nama aksi, bukan tombol tertentu.","en":"Action names like \"move_left\" are created in Project → Project Settings → Input Map. Code uses action names, not specific keys."}}],"workedExample":[{"type":"code","code":"extends Node2D\n\n@export var speed: float = 120.0\n\nfunc _process(delta: float) -> void:\n    var direction := Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\")\n    position += direction * speed * delta\n","caption":{"id":"Gerakan langsung pada `Node2D` memakai delta","en":"Direct `Node2D` movement using delta"}},{"type":"p","text":{"id":"Dalam 2 detik pada 30 FPS: 60 frame × 120 × 0,0333 ≈ 240 piksel. Pada 60 FPS: 120 frame × 120 × 0,0167 ≈ 240 piksel. Sama!","en":"In 2 seconds at 30 FPS: 60 frames × 120 × 0.0333 ≈ 240 pixels. At 60 FPS: 120 frames × 120 × 0.0167 ≈ 240 pixels. The same!"}}],"activity":{"name":{"id":"Lab Gerakan","en":"Movement Lab"},"instructions":[{"id":"Klik area permainan atau tekan Mulai, lalu gerakkan persegi dengan panah/WASD atau tombol di layar.","en":"Click the play area or press Start, then move the square with arrows/WASD or the on-screen buttons."},{"id":"Ubah kecepatan dengan slider dan capai zona target hijau.","en":"Change the speed with the slider and reach the green target zone."},{"id":"Lihat panel perbandingan: matikan \"Pakai delta\", amati, lalu nyalakan lagi.","en":"Watch the comparison panel: turn \"Use delta\" off, observe, then turn it back on."}],"hints":[{"id":"Tanpa delta, objek di 60 FPS bergerak dua kali lebih jauh daripada di 30 FPS.","en":"Without delta, the object at 60 FPS moves twice as far as at 30 FPS."},{"id":"Tekan Escape untuk melepas fokus keyboard dari permainan.","en":"Press Escape to release keyboard focus from the game."}],"initialConfig":{"kind":"movement","v":1,"speed":120,"useDelta":true},"limits":{"maxEntities":4,"maxSeconds":1200}},"checks":["movement.reach_target","movement.speed_changed","movement.delta_compared"],"checkLabels":{"movement.reach_target":{"id":"Mencapai zona target","en":"Reached the target zone"},"movement.speed_changed":{"id":"Mencoba kecepatan selain 120","en":"Tried a speed other than 120"},"movement.delta_compared":{"id":"Membandingkan tanpa delta, lalu kembali memakai delta","en":"Compared without delta, then switched delta back on"}},"fidelity":{"teaches":{"id":"Vektor arah, aksi input bernama, dan gerakan berbasis waktu.","en":"Direction vectors, named input actions, and time-based movement."},"differs":[{"id":"Ini JavaScript, bukan mesin Godot. Skala koordinat hanya ilustrasi.","en":"This is JavaScript, not the Godot engine. The coordinate scale is illustrative."},{"id":"Panel 30/60 FPS disimulasikan dalam langkah tetap; FPS asli browser bisa berbeda.","en":"The 30/60 FPS panel is simulated inside a fixed step; the browser''s real FPS can differ."}]},"misconceptions":[{"id":"Kecepatan tanpa delta sudah cukup. (Gerakan akan tergantung FPS.)","en":"Speed without delta is fine. (Movement would depend on FPS.)"},{"id":"Sumbu y positif ke atas. (Di Godot 2D, y positif ke bawah.)","en":"Positive y points up. (In Godot 2D, positive y points down.)"}],"quiz":{"prompt":{"id":"Baris mana yang membuat gerakan tidak tergantung FPS?","en":"Which line makes movement independent of FPS?"},"code":null,"options":[{"id":"position += direction * speed","en":"position += direction * speed"},{"id":"position += direction * speed * delta","en":"position += direction * speed * delta"},{"id":"position = direction * delta","en":"position = direction * delta"}],"answer":1,"explanation":{"id":"Mengalikan dengan delta mengubah piksel/detik menjadi piksel untuk frame ini.","en":"Multiplying by delta converts pixels/second into pixels for this frame."}},"reflection":{"id":"Ceritakan apa yang kamu lihat di panel perbandingan ketika delta dimatikan. Mengapa itu masalah bagi pemain dengan laptop lambat?","en":"Describe what you saw in the comparison panel when delta was off. Why is that a problem for players with slow laptops?"},"transfer":{"steps":[{"id":"Buka Project Settings → Input Map. Tambahkan aksi move_left, move_right, move_up, move_down dan pasangkan tombol.","en":"Open Project Settings → Input Map. Add actions move_left, move_right, move_up, move_down and assign keys."},{"id":"Buat `Node2D` dengan anak `Sprite2D` dan lampirkan skrip di bawah.","en":"Create a `Node2D` with a `Sprite2D` child and attach the script below."},{"id":"Jalankan scene (F6) dan ubah `speed` di Inspector.","en":"Run the scene (F6) and change `speed` in the Inspector."}],"snippet":"extends Node2D\n\n@export var speed: float = 120.0\n\nfunc _process(delta: float) -> void:\n    var direction := Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\")\n    position += direction * speed * delta\n","question":{"id":"Apa arti `delta` di `_process(delta)`, dan apa yang terjadi jika kamu menghapus `* delta` dari skrip?","en":"What does `delta` mean in `_process(delta)`, and what happens if you remove `* delta` from the script?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('collision', 1, 3, 'collision', '{"key":"collision","version":1,"module":3,"kind":"collision","godotVersion":"4.6","title":{"id":"Tabrakan","en":"Collisions"},"summary":{"id":"Bergerak di antara dinding, lalu atur layer dan mask agar air tidak menghalangi.","en":"Move between walls, then set layers and masks so water stops blocking you."},"minutes":{"explain":10,"practice":15},"objective":{"id":"Menjelaskan `CharacterBody2D`, `velocity`, `move_and_slide()`, dan collision layer/mask.","en":"Explain `CharacterBody2D`, `velocity`, `move_and_slide()`, and collision layers/masks."},"whyGodot":{"id":"Dinding, lantai, dan musuh di Godot bekerja lewat tabrakan. Layer dan mask menentukan siapa menabrak siapa.","en":"Walls, floors, and enemies in Godot work through collisions. Layers and masks decide who collides with whom."},"explanation":[{"type":"p","text":{"id":"`CharacterBody2D` adalah node yang kamu gerakkan dengan kode dan berhenti saat menabrak. Ia butuh anak `CollisionShape2D` agar punya bentuk.","en":"`CharacterBody2D` is a node you move with code that stops when it hits something. It needs a `CollisionShape2D` child to have a shape."}},{"type":"p","text":{"id":"`velocity` adalah kecepatan dalam piksel per detik. `move_and_slide()` sudah memakai langkah waktu fisika, jadi JANGAN kalikan velocity dengan delta.","en":"`velocity` is speed in pixels per second. `move_and_slide()` already uses the physics timestep, so DO NOT multiply velocity by delta."}},{"type":"p","text":{"id":"Kode fisika ditulis di `_physics_process`, yang berjalan dengan laju tetap (default 60 kali per detik).","en":"Physics code goes in `_physics_process`, which runs at a fixed rate (60 times per second by default)."}},{"type":"list","items":[{"id":"Collision layer: di layer mana objek ini berada.","en":"Collision layer: which layers this object is on."},{"id":"Collision mask: layer mana yang dideteksi/ditabrak objek ini.","en":"Collision mask: which layers this object detects/collides with."}]}],"workedExample":[{"type":"code","code":"extends CharacterBody2D\n\n@export var speed: float = 160.0\n\nfunc _physics_process(_delta: float) -> void:\n    var direction := Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\")\n    velocity = direction * speed\n    move_and_slide()\n","caption":{"id":"Pengendali top-down dengan `CharacterBody2D`","en":"Top-down controller with `CharacterBody2D`"}},{"type":"callout","tone":"warning","text":{"id":"Bandingkan dengan Modul 2: `Node2D` memakai `position += ... * delta`. `CharacterBody2D` memakai `velocity` tanpa delta lalu `move_and_slide()`. Dua model gerak yang berbeda.","en":"Compare with Module 2: `Node2D` uses `position += ... * delta`. `CharacterBody2D` uses `velocity` without delta, then `move_and_slide()`. Two different movement models."}}],"activity":{"name":{"id":"Lab Tabrakan","en":"Collision Lab"},"instructions":[{"id":"Gerakkan pemain dan tabrak dinding abu-abu. Perhatikan pemain berhenti.","en":"Move the player and bump into the grey walls. Notice the player stops."},{"id":"Kolam biru ada di layer 2 (Air). Pemain saat ini mendeteksi layer 1 (Dinding) dan layer 2.","en":"The blue pool is on layer 2 (Water). The player currently detects layer 1 (Walls) and layer 2."},{"id":"Ubah mask pemain agar bisa melewati air tetapi tetap tertahan dinding, lalu capai bendera.","en":"Change the player''s mask so it can pass through water but is still blocked by walls, then reach the flag."}],"hints":[{"id":"Hanya mask pemain yang perlu diubah. Dinding harus tetap memblokir.","en":"Only the player''s mask needs to change. Walls must keep blocking."},{"id":"Jalan lewat atas terlalu sempit; jalan pintas ada di kolam.","en":"The top route is too narrow; the shortcut goes through the pool."}],"initialConfig":{"kind":"collision","v":1,"speed":160,"maskWalls":true,"maskWater":true},"limits":{"maxEntities":20,"maxSeconds":1200}},"checks":["collision.blocked","collision.mask_configured","collision.reach_goal"],"checkLabels":{"collision.blocked":{"id":"Pernah tertahan dinding","en":"Was blocked by a wall"},"collision.mask_configured":{"id":"Mask: Dinding aktif, Air nonaktif","en":"Mask: Walls on, Water off"},"collision.reach_goal":{"id":"Mencapai bendera","en":"Reached the flag"}},"fidelity":{"teaches":{"id":"Gerak terblokir, layer dan mask, serta velocity dalam piksel per detik.","en":"Blocked motion, layers and masks, and velocity in pixels per second."},"differs":[{"id":"Ini pemecah kotak sejajar sumbu (AABB) sederhana, BUKAN mesin fisika Godot.","en":"This is a simple axis-aligned box (AABB) solver, NOT Godot''s physics engine."},{"id":"Tidak ada lereng, sudut lantai, rotasi, atau perilaku `move_and_slide()` yang persis.","en":"There are no slopes, floor angles, rotation, or exact `move_and_slide()` behaviour."},{"id":"Godot punya 32 layer; di sini hanya dua.","en":"Godot has 32 layers; here there are only two."}]},"misconceptions":[{"id":"Velocity harus dikalikan delta sebelum move_and_slide(). (Salah.)","en":"Velocity must be multiplied by delta before move_and_slide(). (Wrong.)"},{"id":"Layer dan mask itu sama. (Layer = di mana aku; mask = apa yang kudeteksi.)","en":"Layer and mask are the same. (Layer = where I am; mask = what I detect.)"}],"quiz":{"prompt":{"id":"Apa yang salah pada kode ini?","en":"What is wrong with this code?"},"code":"func _physics_process(delta: float) -> void:\n    velocity = direction * speed * delta\n    move_and_slide()","options":[{"id":"Tidak ada yang salah.","en":"Nothing is wrong."},{"id":"velocity tidak boleh dikalikan delta; move_and_slide() sudah memakai langkah waktu.","en":"velocity should not be multiplied by delta; move_and_slide() already uses the timestep."},{"id":"move_and_slide() harus dipanggil di _ready().","en":"move_and_slide() must be called in _ready()."}],"answer":1,"explanation":{"id":"Dengan delta, pemain bergerak sekitar 60 kali lebih lambat dari yang diharapkan.","en":"With delta, the player moves about 60 times slower than intended."}},"reflection":{"id":"Jelaskan dengan kata-katamu sendiri perbedaan collision layer dan collision mask, memakai contoh dari lab.","en":"Explain in your own words the difference between collision layer and collision mask, using an example from the lab."},"transfer":{"steps":[{"id":"Buka scene Player (CharacterBody2D) dari Modul 1. Beri `CollisionShape2D` bentuk RectangleShape2D.","en":"Open the Player scene (CharacterBody2D) from Module 1. Give `CollisionShape2D` a RectangleShape2D shape."},{"id":"Lampirkan skrip di bawah. Pastikan aksi Input Map dari Modul 2 ada.","en":"Attach the script below. Make sure the Input Map actions from Module 2 exist."},{"id":"Buat dinding dengan `StaticBody2D` + `CollisionShape2D`.","en":"Create walls with `StaticBody2D` + `CollisionShape2D`."},{"id":"Di Inspector → Collision, ubah Layer dan Mask lalu uji kapan pemain tertahan.","en":"In Inspector → Collision, change Layer and Mask and test when the player is blocked."}],"snippet":"extends CharacterBody2D\n\n@export var speed: float = 160.0\n\nfunc _physics_process(_delta: float) -> void:\n    var direction := Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\")\n    velocity = direction * speed\n    move_and_slide()\n","question":{"id":"Mengapa skrip ini memakai `_physics_process` dan tidak mengalikan `velocity` dengan delta?","en":"Why does this script use `_physics_process` and not multiply `velocity` by delta?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('input-feel', 1, 4, 'input', '{"key":"input-feel","version":1,"module":4,"kind":"input","godotVersion":"4.6","title":{"id":"Input dan rasa kontrol","en":"Input and player feel"},"summary":{"id":"Perbaiki gerakan diagonal yang terlalu cepat dan bedakan tombol ditahan dengan baru ditekan.","en":"Fix diagonal movement that is too fast and tell held keys from just-pressed keys."},"minutes":{"explain":8,"practice":15},"objective":{"id":"Memakai aksi bernama, menormalkan arah diagonal, dan membedakan `is_action_pressed` dengan `is_action_just_pressed`.","en":"Use named actions, normalize diagonal direction, and distinguish `is_action_pressed` from `is_action_just_pressed`."},"whyGodot":{"id":"Kontrol yang terasa adil membuat game menyenangkan. Pemain menyadari jika berjalan diagonal lebih cepat.","en":"Controls that feel fair make a game fun. Players notice when walking diagonally is faster."},"explanation":[{"type":"p","text":{"id":"Jika kanan = (1, 0) dan bawah = (0, 1), maka kanan+bawah = (1, 1). Panjang vektor itu sekitar 1,41, jadi pemain bergerak 41% lebih cepat secara diagonal.","en":"If right = (1, 0) and down = (0, 1), then right+down = (1, 1). That vector''s length is about 1.41, so the player moves 41% faster diagonally."}},{"type":"p","text":{"id":"Menormalkan vektor membuat panjangnya 1. `Input.get_vector()` sudah mengembalikan vektor yang panjangnya paling banyak 1.","en":"Normalizing a vector makes its length 1. `Input.get_vector()` already returns a vector with length at most 1."}},{"type":"list","items":[{"id":"`Input.is_action_pressed(\"dash\")`: benar selama tombol ditahan (setiap frame).","en":"`Input.is_action_pressed(\"dash\")`: true while the key is held (every frame)."},{"id":"`Input.is_action_just_pressed(\"dash\")`: benar hanya pada frame saat tombol mulai ditekan.","en":"`Input.is_action_just_pressed(\"dash\")`: true only on the frame the key goes down."}]}],"workedExample":[{"type":"code","code":"extends CharacterBody2D\n\n@export var speed: float = 160.0\n@export var dash_speed: float = 480.0\n\nfunc _physics_process(_delta: float) -> void:\n    var direction := Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\")\n    velocity = direction * speed\n    if Input.is_action_just_pressed(\"dash\"):\n        velocity = direction * dash_speed\n    move_and_slide()\n","caption":{"id":"Dash sekali per tekan dengan `is_action_just_pressed`","en":"One dash per press with `is_action_just_pressed`"}}],"activity":{"name":{"id":"Lab Kontrol","en":"Control Lab"},"instructions":[{"id":"Gerakkan pemain diagonal (misalnya kanan + bawah) dan lihat rasio kecepatan diagonal.","en":"Move the player diagonally (e.g. right + down) and look at the diagonal speed ratio."},{"id":"Aktifkan \"Normalkan diagonal\" dan uji lagi.","en":"Turn on \"Normalize diagonal\" and test again."},{"id":"Tahan tombol dash. Bandingkan mode \"ditahan\" dengan \"baru ditekan\" di jejak input.","en":"Hold the dash key. Compare \"held\" mode with \"just pressed\" in the input trace."}],"hints":[{"id":"Rasio 1,41 berarti diagonal lebih cepat. Targetnya 1,00.","en":"A ratio of 1.41 means diagonal is faster. The target is 1.00."},{"id":"Dash yang adil terjadi sekali per tekan.","en":"A fair dash happens once per press."}],"initialConfig":{"kind":"input","v":1,"normalizeDiagonal":false,"dashMode":"held","dashKey":"Space"},"limits":{"maxEntities":4,"maxSeconds":1200}},"checks":["input.normalized","input.diagonal_tested","input.just_pressed"],"checkLabels":{"input.normalized":{"id":"Diagonal dinormalkan","en":"Diagonal is normalized"},"input.diagonal_tested":{"id":"Diuji diagonal dengan rasio ≤ 1,01","en":"Tested diagonally with ratio ≤ 1.01"},"input.just_pressed":{"id":"Dash memakai \"baru ditekan\"","en":"Dash uses \"just pressed\""}},"fidelity":{"teaches":{"id":"Aksi bernama, normalisasi vektor, dan perbedaan ditahan/baru ditekan.","en":"Named actions, vector normalization, and held versus just-pressed."},"differs":[{"id":"Pemetaan tombol di sini terbatas; Input Map Godot mendukung banyak perangkat dan deadzone.","en":"Key mapping here is limited; Godot''s Input Map supports many devices and deadzones."},{"id":"Status \"baru ditekan\" dihitung per langkah simulasi browser, bukan frame mesin Godot.","en":"\"Just pressed\" is computed per browser simulation step, not per Godot engine frame."}]},"misconceptions":[{"id":"Menjumlahkan dua arah selalu memberi kecepatan yang sama. (Diagonal jadi ~1,41×.)","en":"Adding two directions always gives the same speed. (Diagonal becomes ~1.41×.)"},{"id":"is_action_pressed cocok untuk lompat atau dash. (Itu akan aktif setiap frame.)","en":"is_action_pressed is right for jump or dash. (It would trigger every frame.)"}],"quiz":{"prompt":{"id":"Fungsi mana yang cocok untuk menembak sekali per tekan tombol?","en":"Which function fits firing once per key press?"},"code":null,"options":[{"id":"Input.is_action_pressed(\"fire\")","en":"Input.is_action_pressed(\"fire\")"},{"id":"Input.is_action_just_pressed(\"fire\")","en":"Input.is_action_just_pressed(\"fire\")"},{"id":"Input.get_vector(\"fire\", \"fire\", \"fire\", \"fire\")","en":"Input.get_vector(\"fire\", \"fire\", \"fire\", \"fire\")"}],"answer":1,"explanation":{"id":"just_pressed hanya benar pada frame saat tombol mulai ditekan.","en":"just_pressed is only true on the frame the key goes down."}},"reflection":{"id":"Apa yang dirasakan pemain jika diagonal lebih cepat atau dash aktif terus saat ditahan? Bagaimana kamu memperbaikinya?","en":"How would a player feel if diagonal were faster or the dash fired continuously while held? How did you fix it?"},"transfer":{"steps":[{"id":"Tambahkan aksi `dash` di Input Map dan pasangkan Spasi.","en":"Add a `dash` action to the Input Map and assign Space."},{"id":"Perbarui skrip Player dengan contoh di bawah.","en":"Update the Player script with the example below."},{"id":"Ganti sementara `is_action_just_pressed` dengan `is_action_pressed` dan rasakan bedanya.","en":"Temporarily swap `is_action_just_pressed` for `is_action_pressed` and feel the difference."}],"snippet":"extends CharacterBody2D\n\n@export var speed: float = 160.0\n@export var dash_speed: float = 480.0\n\nfunc _physics_process(_delta: float) -> void:\n    var direction := Input.get_vector(\"move_left\", \"move_right\", \"move_up\", \"move_down\")\n    velocity = direction * speed\n    if Input.is_action_just_pressed(\"dash\"):\n        velocity = direction * dash_speed\n    move_and_slide()\n","question":{"id":"Mengapa `Input.get_vector()` membuat gerakan diagonal adil, dan kapan kamu memilih `is_action_just_pressed`?","en":"Why does `Input.get_vector()` make diagonal movement fair, and when do you choose `is_action_just_pressed`?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('signals', 1, 5, 'signals', '{"key":"signals","version":1,"module":5,"kind":"signals","godotVersion":"4.6","title":{"id":"Signal dan interaksi","en":"Signals and interactions"},"summary":{"id":"Hubungkan peristiwa (signal) ke reaksi: koin menambah skor, skor membuka pintu.","en":"Connect events (signals) to reactions: coins add score, score opens the door."},"minutes":{"explain":8,"practice":15},"objective":{"id":"Menghubungkan signal seperti `body_entered` dari `Area2D` ke fungsi reaksi dan menelusuri urutan peristiwa.","en":"Connect signals such as `Area2D`''s `body_entered` to reaction functions and trace event order."},"whyGodot":{"id":"Signal membuat node saling memberi tahu tanpa saling bergantung erat. Koin tidak perlu tahu cara kerja HUD.","en":"Signals let nodes notify each other without being tightly coupled. A coin does not need to know how the HUD works."},"explanation":[{"type":"p","text":{"id":"Signal adalah pesan \"sesuatu terjadi\". `Area2D` memancarkan `body_entered` SATU KALI saat sebuah body mulai masuk, bukan terus-menerus selama tumpang tindih.","en":"A signal is a \"something happened\" message. `Area2D` emits `body_entered` ONCE when a body starts entering, not continuously while overlapping."}},{"type":"p","text":{"id":"Kamu bisa menghubungkan signal di tab Node (dock Signals) atau dengan kode `signal_name.connect(callback)`.","en":"You can connect signals in the Node tab (Signals dock) or in code with `signal_name.connect(callback)`."}},{"type":"list","items":[{"id":"Peristiwa: koin dimasuki pemain → reaksi: tambah skor.","en":"Event: coin entered by player → reaction: add score."},{"id":"Peristiwa: skor mencapai target → reaksi: buka pintu.","en":"Event: score reaches goal → reaction: open door."},{"id":"Peristiwa: pintu keluar dimasuki → reaksi: menang.","en":"Event: exit entered → reaction: win."}]}],"workedExample":[{"type":"code","code":"extends Area2D\n\nsignal collected\n\nfunc _ready() -> void:\n    body_entered.connect(_on_body_entered)\n\nfunc _on_body_entered(body: Node2D) -> void:\n    if body.name == \"Player\":\n        collected.emit()\n        queue_free()\n","caption":{"id":"Koin `Area2D` yang memancarkan signal `collected`","en":"An `Area2D` coin that emits a `collected` signal"}}],"activity":{"name":{"id":"Lab Signal","en":"Signal Lab"},"instructions":[{"id":"Pilih reaksi untuk tiap signal di panel Koneksi.","en":"Choose a reaction for each signal in the Connections panel."},{"id":"Kumpulkan koin, buka pintu, dan capai pintu keluar. Lihat jejak peristiwa.","en":"Collect coins, open the door, and reach the exit. Watch the event trace."},{"id":"Coba aktifkan \"Pancarkan terus saat tumpang tindih\" dan diam di atas koin. Lalu matikan lagi.","en":"Try turning on \"Emit continuously while overlapping\" and stand on a coin. Then turn it off again."}],"hints":[{"id":"Pintu hanya terbuka lewat reaksi \"buka pintu\".","en":"The door only opens through the \"open door\" reaction."},{"id":"Jika skor naik terus saat diam, signal dipancarkan berulang. Itu bug.","en":"If the score keeps rising while standing still, the signal is repeating. That is a bug."}],"initialConfig":{"kind":"signals","v":1,"coinsRequired":3,"emitWhileOverlapping":false,"connections":{"coin.body_entered":"add_score","score.goal_reached":"none","exit.body_entered":"none"}},"limits":{"maxEntities":12,"maxSeconds":1200}},"checks":["signals.connections","signals.single_entry","signals.won"],"checkLabels":{"signals.connections":{"id":"Koin→tambah skor, target skor→buka pintu, pintu keluar→menang","en":"Coin→add score, score goal→open door, exit→win"},"signals.single_entry":{"id":"Signal hanya saat masuk, tidak berulang","en":"Signal only on entry, not repeating"},"signals.won":{"id":"Menang lewat pintu keluar","en":"Won through the exit"}},"fidelity":{"teaches":{"id":"Peristiwa, koneksi ke reaksi, dan urutan peristiwa.","en":"Events, connections to reactions, and event order."},"differs":[{"id":"Ini pengirim peristiwa sederhana, bukan implementasi signal Godot atau siklus hidup objek.","en":"This is a simple event dispatcher, not Godot''s signal implementation or object lifecycle."},{"id":"Pilihan koneksi sudah ditentukan; di Godot kamu menulis fungsi sendiri.","en":"Connection choices are predefined; in Godot you write your own functions."}]},"misconceptions":[{"id":"body_entered aktif setiap frame selama tumpang tindih. (Hanya sekali saat masuk.)","en":"body_entered fires every frame while overlapping. (Only once on entry.)"},{"id":"Koin harus memanggil HUD langsung. (Lebih baik memancarkan signal.)","en":"The coin must call the HUD directly. (Emitting a signal is better.)"}],"quiz":{"prompt":{"id":"Baris mana yang menghubungkan signal body_entered ke fungsi?","en":"Which line connects the body_entered signal to a function?"},"code":null,"options":[{"id":"body_entered.connect(_on_body_entered)","en":"body_entered.connect(_on_body_entered)"},{"id":"_on_body_entered.connect(body_entered)","en":"_on_body_entered.connect(body_entered)"},{"id":"emit(body_entered)","en":"emit(body_entered)"}],"answer":0,"explanation":{"id":"Format: signal.connect(fungsi_penerima).","en":"Format: signal.connect(receiver_function)."}},"reflection":{"id":"Tuliskan urutan peristiwa dari jejak saat kamu menang. Mengapa urutan itu penting?","en":"Write the order of events from the trace when you won. Why does that order matter?"},"transfer":{"steps":[{"id":"Buat scene Coin: `Area2D` dengan `Sprite2D` dan `CollisionShape2D`.","en":"Create a Coin scene: `Area2D` with `Sprite2D` and `CollisionShape2D`."},{"id":"Lampirkan skrip di bawah. Pastikan body Player bernama \"Player\".","en":"Attach the script below. Make sure the Player body is named \"Player\"."},{"id":"Di scene Main, hubungkan signal `collected` ke fungsi yang menambah skor (tab Node → Signals).","en":"In the Main scene, connect the `collected` signal to a function that adds score (Node tab → Signals)."}],"snippet":"extends Area2D\n\nsignal collected\n\nfunc _ready() -> void:\n    body_entered.connect(_on_body_entered)\n\nfunc _on_body_entered(body: Node2D) -> void:\n    if body.name == \"Player\":\n        collected.emit()\n        queue_free()\n","question":{"id":"Apa perbedaan \"masuk area\" dan \"tumpang tindih terus-menerus\", dan signal mana yang kamu pakai untuk mengambil koin?","en":"What is the difference between \"entering an area\" and \"overlapping continuously\", and which signal do you use to pick up a coin?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('state-ui', 1, 6, 'state', '{"key":"state-ui","version":1,"module":6,"kind":"state","godotVersion":"4.6","title":{"id":"State game dan UI","en":"Game state and UI"},"summary":{"id":"Atur nyawa dan target, temukan bug skor lama saat restart, dan tampilkan HUD.","en":"Set lives and a goal, find the stale-score restart bug, and show a HUD."},"minutes":{"explain":8,"practice":15},"objective":{"id":"Mengelola state bermain/menang/kalah, memperbarui `Label` di `CanvasLayer`, dan me-restart tanpa data lama.","en":"Manage playing/won/lost states, update a `Label` in a `CanvasLayer`, and restart without stale data."},"whyGodot":{"id":"Setiap game butuh awal, kemenangan, kekalahan, dan restart yang bersih.","en":"Every game needs a start, a win, a loss, and a clean restart."},"explanation":[{"type":"p","text":{"id":"State adalah \"mode\" game saat ini: PLAYING, WON, atau LOST. Kode memeriksa state sebelum bertindak, misalnya tidak menambah skor setelah kalah.","en":"State is the game''s current \"mode\": PLAYING, WON, or LOST. Code checks the state before acting, for example not adding score after losing."}},{"type":"p","text":{"id":"HUD dibuat dengan node `Control` seperti `Label`, biasanya di dalam `CanvasLayer` agar tetap di layar saat kamera bergerak.","en":"A HUD is made with `Control` nodes like `Label`, usually inside a `CanvasLayer` so it stays on screen when the camera moves."}},{"type":"callout","tone":"warning","text":{"id":"Bug umum: tombol restart mengubah state ke PLAYING tetapi lupa mengembalikan skor dan nyawa. Pemain memulai dengan data lama.","en":"Common bug: the restart button sets state to PLAYING but forgets to reset score and lives. The player starts with stale data."}}],"workedExample":[{"type":"code","code":"extends Node\n\nenum State { PLAYING, WON, LOST }\n\n@export var start_lives: int = 3\n@export var goal: int = 5\n\nvar state: State = State.PLAYING\nvar score: int = 0\nvar lives: int = 0\n\n@onready var label: Label = $CanvasLayer/Label\n\nfunc _ready() -> void:\n    restart()\n\nfunc restart() -> void:\n    score = 0\n    lives = start_lives\n    state = State.PLAYING\n    update_hud()\n\nfunc add_point() -> void:\n    if state != State.PLAYING:\n        return\n    score += 1\n    if score >= goal:\n        state = State.WON\n    update_hud()\n\nfunc lose_life() -> void:\n    if state != State.PLAYING:\n        return\n    lives -= 1\n    if lives <= 0:\n        state = State.LOST\n    update_hud()\n\nfunc update_hud() -> void:\n    label.text = \"Score: %d  Lives: %d\" % [score, lives]\n","caption":{"id":"Pengelola state sederhana dengan HUD","en":"A simple state manager with a HUD"}}],"activity":{"name":{"id":"Lab State","en":"State Lab"},"instructions":[{"id":"Atur nyawa dan target bintang, lalu mainkan sampai menang.","en":"Set lives and the star goal, then play until you win."},{"id":"Mainkan lagi dan sengaja kalah dengan menabrak bahaya merah.","en":"Play again and lose on purpose by touching the red hazards."},{"id":"Tekan Restart. Apakah skor dan nyawa kembali benar? Perbaiki pengaturan restart.","en":"Press Restart. Do score and lives reset correctly? Fix the restart settings."}],"hints":[{"id":"Restart yang bersih: skor 0 dan nyawa sesuai pengaturan.","en":"A clean restart: score 0 and lives as configured."},{"id":"Kamu kebal sebentar setelah kehilangan nyawa.","en":"You are briefly invulnerable after losing a life."}],"initialConfig":{"kind":"state","v":1,"lives":3,"goal":5,"resetScoreOnRestart":false,"resetLivesOnRestart":false},"limits":{"maxEntities":16,"maxSeconds":1200}},"checks":["state.reset_clean","state.reached_won","state.reached_lost","state.restart_tested"],"checkLabels":{"state.reset_clean":{"id":"Restart mengembalikan skor dan nyawa","en":"Restart resets score and lives"},"state.reached_won":{"id":"Mencapai state MENANG","en":"Reached the WON state"},"state.reached_lost":{"id":"Mencapai state KALAH","en":"Reached the LOST state"},"state.restart_tested":{"id":"Restart bersih berhasil diuji","en":"A clean restart was tested"}},"fidelity":{"teaches":{"id":"State eksplisit, transisi, HUD, dan reset yang bersih.","en":"Explicit state, transitions, HUD, and clean reset."},"differs":[{"id":"HUD di sini adalah HTML biasa, bukan node `Control` Godot.","en":"The HUD here is plain HTML, not Godot `Control` nodes."},{"id":"Penjadwalan browser dan jeda tab dapat berbeda dari waktu mesin.","en":"Browser scheduling and tab pausing can differ from engine time."}]},"misconceptions":[{"id":"Mengubah state ke PLAYING sudah cukup untuk restart. (Data juga harus di-reset.)","en":"Setting state to PLAYING is enough to restart. (Data must be reset too.)"},{"id":"HUD harus digambar ulang dengan kode setiap frame. (Perbarui saat nilai berubah.)","en":"The HUD must be redrawn in code every frame. (Update when values change.)"}],"quiz":{"prompt":{"id":"Di contoh kode, mengapa `add_point()` memeriksa `state != State.PLAYING`?","en":"In the example, why does `add_point()` check `state != State.PLAYING`?"},"code":"func add_point() -> void:\n    if state != State.PLAYING:\n        return\n    score += 1","options":[{"id":"Agar skor tidak bertambah setelah menang atau kalah.","en":"So the score does not increase after winning or losing."},{"id":"Agar kode berjalan lebih cepat.","en":"So the code runs faster."},{"id":"Karena GDScript mewajibkannya.","en":"Because GDScript requires it."}],"answer":0,"explanation":{"id":"Pemeriksaan state mencegah perubahan data saat game sudah selesai.","en":"The state check prevents data changes once the game is over."}},"reflection":{"id":"Jelaskan bug restart yang kamu temukan dan bagaimana kamu membuktikan perbaikannya.","en":"Explain the restart bug you found and how you proved the fix."},"transfer":{"steps":[{"id":"Tambahkan `CanvasLayer` dengan `Label` ke scene Main.","en":"Add a `CanvasLayer` with a `Label` to the Main scene."},{"id":"Lampirkan skrip contoh ke node Main dan sesuaikan path `$CanvasLayer/Label`.","en":"Attach the example script to the Main node and adjust the `$CanvasLayer/Label` path."},{"id":"Panggil `add_point()` dari signal koin dan `restart()` dari tombol (`Button` → signal `pressed`).","en":"Call `add_point()` from the coin signal and `restart()` from a button (`Button` → `pressed` signal)."}],"snippet":"extends Node\n\nenum State { PLAYING, WON, LOST }\n\n@export var start_lives: int = 3\n@export var goal: int = 5\n\nvar state: State = State.PLAYING\nvar score: int = 0\nvar lives: int = 0\n\n@onready var label: Label = $CanvasLayer/Label\n\nfunc _ready() -> void:\n    restart()\n\nfunc restart() -> void:\n    score = 0\n    lives = start_lives\n    state = State.PLAYING\n    update_hud()\n\nfunc add_point() -> void:\n    if state != State.PLAYING:\n        return\n    score += 1\n    if score >= goal:\n        state = State.WON\n    update_hud()\n\nfunc lose_life() -> void:\n    if state != State.PLAYING:\n        return\n    lives -= 1\n    if lives <= 0:\n        state = State.LOST\n    update_hud()\n\nfunc update_hud() -> void:\n    label.text = \"Score: %d  Lives: %d\" % [score, lives]\n","question":{"id":"Apa saja yang harus di-reset di fungsi `restart()`, dan bagaimana kamu menguji bahwa tidak ada data lama yang tersisa?","en":"What must be reset in the `restart()` function, and how do you test that no stale data remains?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('timers', 1, 7, 'timer', '{"key":"timers","version":1,"module":7,"kind":"timer","godotVersion":"4.6","title":{"id":"Waktu dan umpan balik","en":"Time and feedback"},"summary":{"id":"Atur hitung mundur dan timer kemunculan, lalu cegah objek muncul tanpa batas.","en":"Set a countdown and a spawn timer, then stop objects from spawning without limit."},"minutes":{"explain":8,"practice":15},"objective":{"id":"Memakai node `Timer` dengan `timeout`, membedakan one-shot dan berulang, dan membatasi jumlah objek.","en":"Use the `Timer` node with `timeout`, distinguish one-shot from repeating, and cap the number of objects."},"whyGodot":{"id":"Timer mengatur ritme game: musuh muncul, power-up habis, dan waktu permainan berakhir.","en":"Timers set a game''s rhythm: enemies spawn, power-ups expire, and play time ends."},"explanation":[{"type":"p","text":{"id":"Node `Timer` menghitung mundur `wait_time` detik lalu memancarkan signal `timeout`.","en":"The `Timer` node counts down `wait_time` seconds, then emits the `timeout` signal."}},{"type":"list","items":[{"id":"`one_shot = true`: berhenti setelah satu kali timeout. Cocok untuk hitung mundur permainan.","en":"`one_shot = true`: stops after one timeout. Good for a game countdown."},{"id":"`one_shot = false`: berulang terus. Cocok untuk memunculkan objek secara berkala.","en":"`one_shot = false`: repeats forever. Good for spawning objects periodically."}]},{"type":"p","text":{"id":"Timer berulang tanpa batas jumlah objek dapat membuat ratusan objek dan memperlambat laptop. Selalu beri batas.","en":"A repeating timer with no object limit can create hundreds of objects and slow a laptop. Always set a limit."}},{"type":"callout","tone":"tip","text":{"id":"Umpan balik kecil (berkedip, berubah warna) dibuat di Godot dengan `AnimationPlayer` atau `Tween`. Lab ini hanya menunjukkan konsepnya.","en":"Small feedback (flashing, colour change) is made in Godot with `AnimationPlayer` or `Tween`. This lab only shows the concept."}}],"workedExample":[{"type":"code","code":"extends Node2D\n\n@export var item_scene: PackedScene\n@export var max_items: int = 10\n\n@onready var countdown: Timer = $Countdown\n@onready var spawn_timer: Timer = $SpawnTimer\n\nfunc _ready() -> void:\n    countdown.one_shot = true\n    countdown.timeout.connect(_on_countdown_timeout)\n    spawn_timer.timeout.connect(_on_spawn_timer_timeout)\n    countdown.start(30.0)\n    spawn_timer.start(1.5)\n\nfunc _on_spawn_timer_timeout() -> void:\n    if get_tree().get_nodes_in_group(\"items\").size() >= max_items:\n        return\n    var item := item_scene.instantiate()\n    item.add_to_group(\"items\")\n    add_child(item)\n\nfunc _on_countdown_timeout() -> void:\n    spawn_timer.stop()\n    print(\"Time''s up!\")\n","caption":{"id":"Hitung mundur one-shot dan kemunculan berulang yang dibatasi","en":"One-shot countdown and capped repeating spawns"}}],"activity":{"name":{"id":"Lab Timer","en":"Timer Lab"},"instructions":[{"id":"Atur lama hitung mundur dan jarak kemunculan, lalu tangkap bintang yang jatuh.","en":"Set the countdown length and spawn interval, then catch the falling stars."},{"id":"Matikan batas objek dan jarak kemunculan terkecil. Amati jumlah objek.","en":"Turn off the object cap and use the smallest spawn interval. Watch the object count."},{"id":"Perbaiki: hitung mundur one-shot dan batas objek aktif. Biarkan waktu habis.","en":"Fix it: one-shot countdown and the object cap on. Let the time run out."}],"hints":[{"id":"Jika hitung mundur tidak one-shot, \"waktu habis\" terjadi berulang kali.","en":"If the countdown is not one-shot, \"time''s up\" happens again and again."},{"id":"Batas keras lab adalah 100 objek untuk melindungi laptop.","en":"The lab''s hard limit is 100 objects to protect the laptop."}],"initialConfig":{"kind":"timer","v":1,"countdownSeconds":20,"countdownOneShot":false,"spawnInterval":1.5,"capEnabled":false,"maxEntities":10},"limits":{"maxEntities":100,"maxSeconds":1200}},"checks":["timer.oneshot_countdown","timer.bounded_spawn","timer.ran_to_timeout"],"checkLabels":{"timer.oneshot_countdown":{"id":"Hitung mundur one-shot","en":"Countdown is one-shot"},"timer.bounded_spawn":{"id":"Kemunculan dibatasi (≤ 30)","en":"Spawning is capped (≤ 30)"},"timer.ran_to_timeout":{"id":"Hitung mundur berjalan sampai timeout","en":"The countdown ran to timeout"}},"fidelity":{"teaches":{"id":"Timeout, one-shot versus berulang, dan kemunculan terbatas.","en":"Timeouts, one-shot versus repeating, and bounded spawning."},"differs":[{"id":"Timer dihitung per langkah simulasi browser; Godot memakai waktu idle atau fisika dan bisa dijeda berbeda.","en":"Timers count per browser simulation step; Godot uses idle or physics time and pauses differently."},{"id":"Tidak ada AnimationPlayer di sini; kedipan hanyalah gambar sederhana.","en":"There is no AnimationPlayer here; flashes are simple drawing."}]},"misconceptions":[{"id":"Timer berhenti sendiri setelah timeout. (Hanya jika one_shot = true.)","en":"A Timer stops by itself after timeout. (Only if one_shot = true.)"},{"id":"Memunculkan objek tidak perlu dibatasi. (Bisa membuat game lambat.)","en":"Spawning does not need a limit. (It can make the game slow.)"}],"quiz":{"prompt":{"id":"Timer dengan wait_time = 2 dan one_shot = false berjalan 7 detik. Berapa kali timeout?","en":"A Timer with wait_time = 2 and one_shot = false runs for 7 seconds. How many timeouts?"},"code":null,"options":[{"id":"1","en":"1"},{"id":"3","en":"3"},{"id":"7","en":"7"}],"answer":1,"explanation":{"id":"Timeout pada detik 2, 4, dan 6 = 3 kali.","en":"Timeouts at seconds 2, 4, and 6 = 3 times."}},"reflection":{"id":"Apa yang terjadi pada jumlah objek tanpa batas, dan bagaimana batas melindungi pemain dengan laptop lambat?","en":"What happened to the object count without a cap, and how does a cap protect players with slow laptops?"},"transfer":{"steps":[{"id":"Tambahkan dua node `Timer`: Countdown dan SpawnTimer.","en":"Add two `Timer` nodes: Countdown and SpawnTimer."},{"id":"Lampirkan skrip contoh dan pilih scene item di Inspector.","en":"Attach the example script and choose an item scene in the Inspector."},{"id":"Tambahkan `AnimationPlayer` sederhana untuk membuat item berkedip saat muncul.","en":"Add a simple `AnimationPlayer` to make items flash when they appear."}],"snippet":"extends Node2D\n\n@export var item_scene: PackedScene\n@export var max_items: int = 10\n\n@onready var countdown: Timer = $Countdown\n@onready var spawn_timer: Timer = $SpawnTimer\n\nfunc _ready() -> void:\n    countdown.one_shot = true\n    countdown.timeout.connect(_on_countdown_timeout)\n    spawn_timer.timeout.connect(_on_spawn_timer_timeout)\n    countdown.start(30.0)\n    spawn_timer.start(1.5)\n\nfunc _on_spawn_timer_timeout() -> void:\n    if get_tree().get_nodes_in_group(\"items\").size() >= max_items:\n        return\n    var item := item_scene.instantiate()\n    item.add_to_group(\"items\")\n    add_child(item)\n\nfunc _on_countdown_timeout() -> void:\n    spawn_timer.stop()\n    print(\"Time''s up!\")\n","question":{"id":"Kapan kamu memakai Timer one-shot dan kapan berulang? Mengapa kemunculan objek perlu batas?","en":"When do you use a one-shot Timer and when a repeating one? Why does spawning need a limit?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.lesson_versions (lesson_key, version, module_no, activity_kind, content) values ('mini-game', 1, 8, 'loop', '{"key":"mini-game","version":1,"module":8,"kind":"loop","godotVersion":"4.6","title":{"id":"Game lengkap dan debugging","en":"Complete loop and debugging"},"summary":{"id":"Gabungkan semua konsep menjadi game kumpulkan-dan-keluar, lalu perbaiki dua bug.","en":"Combine every concept into a collect-and-exit game, then fix two bugs."},"minutes":{"explain":8,"practice":20},"objective":{"id":"Mengintegrasikan scene, input, tabrakan, signal, state, dan timer serta men-debug dengan pengujian terencana.","en":"Integrate scenes, input, collision, signals, state, and timers, and debug with planned tests."},"whyGodot":{"id":"Proyek akhirmu adalah satu loop lengkap seperti ini. Debugging adalah bagian normal dari membuat game.","en":"Your final project is one complete loop like this. Debugging is a normal part of making games."},"explanation":[{"type":"p","text":{"id":"Loop game: mulai → kumpulkan koin sambil menghindari bahaya → pintu keluar terbuka → menang. Jika nyawa habis → kalah. Restart → mulai lagi bersih.","en":"Game loop: start → collect coins while avoiding hazards → exit opens → win. If lives run out → lose. Restart → start again cleanly."}},{"type":"p","text":{"id":"Uji setiap jalur dengan sengaja: jalur menang, jalur kalah, dan restart. Satu jalur yang lolos tidak membuktikan jalur lain benar.","en":"Test every path on purpose: the win path, the lose path, and restart. One passing path does not prove the others are correct."}},{"type":"list","items":[{"id":"Bug 1: pintu keluar terbuka terlalu cepat.","en":"Bug 1: the exit opens too early."},{"id":"Bug 2: setelah restart, koin yang sudah diambil tidak kembali.","en":"Bug 2: after restart, collected coins do not come back."}]}],"workedExample":[{"type":"code","code":"extends Area2D\n\n@export var coins_total: int = 4\n\nvar coins_collected: int = 0\n\nfunc _ready() -> void:\n    body_entered.connect(_on_body_entered)\n\nfunc on_coin_collected() -> void:\n    coins_collected += 1\n\nfunc _on_body_entered(body: Node2D) -> void:\n    if body.name == \"Player\" and coins_collected >= coins_total:\n        get_tree().change_scene_to_file(\"res://win.tscn\")\n","caption":{"id":"Pintu keluar yang memeriksa semua koin sudah terkumpul","en":"An exit that checks all coins have been collected"}},{"type":"p","text":{"id":"Ubah satu hal, uji lagi, lalu catat hasilnya. Ini cara debugging yang dapat diulang.","en":"Change one thing, test again, then record the result. This is repeatable debugging."}}],"activity":{"name":{"id":"Lab Mini-game","en":"Mini-game Lab"},"instructions":[{"id":"Mainkan game. Temukan kapan pintu keluar terbuka dan apa yang terjadi setelah restart.","en":"Play the game. Find when the exit opens and what happens after restart."},{"id":"Pilih perbaikan yang benar untuk aturan pintu keluar dan aturan restart.","en":"Choose the right fix for the exit rule and the restart rule."},{"id":"Buktikan: menang sekali, kalah sekali, dan lakukan restart bersih.","en":"Prove it: win once, lose once, and do a clean restart."}],"hints":[{"id":"Pintu harus menunggu SEMUA koin, bukan hanya satu.","en":"The exit must wait for ALL coins, not just one."},{"id":"Restart bersih mengembalikan koin, skor, nyawa, dan posisi.","en":"A clean restart restores coins, score, lives, and position."}],"initialConfig":{"kind":"loop","v":1,"exitRule":"score_gt_zero","restartRule":"keep_coins","lives":3},"limits":{"maxEntities":20,"maxSeconds":1200}},"checks":["loop.bug_exit_fixed","loop.bug_restart_fixed","loop.win_path","loop.lose_path","loop.restart_path"],"checkLabels":{"loop.bug_exit_fixed":{"id":"Bug 1 diperbaiki: pintu menunggu semua koin","en":"Bug 1 fixed: exit waits for all coins"},"loop.bug_restart_fixed":{"id":"Bug 2 diperbaiki: restart mengembalikan koin","en":"Bug 2 fixed: restart restores coins"},"loop.win_path":{"id":"Jalur menang diuji","en":"Win path tested"},"loop.lose_path":{"id":"Jalur kalah diuji","en":"Lose path tested"},"loop.restart_path":{"id":"Restart bersih diuji","en":"Clean restart tested"}},"fidelity":{"teaches":{"id":"Integrasi konsep, pengujian jalur, dan debugging terencana.","en":"Concept integration, path testing, and planned debugging."},"differs":[{"id":"Blok-blok game sudah tetap; di Godot kamu membuat scene dan skrip sendiri.","en":"The game blocks are fixed; in Godot you build your own scenes and scripts."},{"id":"Tabrakan memakai kotak sederhana, bukan fisika Godot.","en":"Collisions use simple boxes, not Godot physics."}]},"misconceptions":[{"id":"Jika menang berhasil sekali, game sudah benar. (Uji juga kalah dan restart.)","en":"If winning works once, the game is correct. (Also test losing and restart.)"},{"id":"Bug selalu menimbulkan error. (Banyak bug hanya perilaku yang salah.)","en":"Bugs always cause errors. (Many bugs are just wrong behaviour.)"}],"quiz":{"prompt":{"id":"Kondisi mana yang benar untuk membuka pintu keluar setelah semua koin terkumpul?","en":"Which condition correctly opens the exit after all coins are collected?"},"code":null,"options":[{"id":"coins_collected > 0","en":"coins_collected > 0"},{"id":"coins_collected >= coins_total","en":"coins_collected >= coins_total"},{"id":"coins_total >= 0","en":"coins_total >= 0"}],"answer":1,"explanation":{"id":"Pintu harus menunggu sampai jumlah terkumpul mencapai total.","en":"The exit must wait until the collected count reaches the total."}},"reflection":{"id":"Jelaskan dua bug yang kamu perbaiki: gejalanya, penyebabnya, dan bagaimana kamu menguji perbaikannya.","en":"Explain the two bugs you fixed: the symptom, the cause, and how you tested the fix."},"transfer":{"steps":[{"id":"Buat ulang loop kecil di Godot: Player, 3–4 Coin (instance), Hazard, Exit, dan HUD.","en":"Recreate a tiny loop in Godot: Player, 3–4 Coin instances, a Hazard, an Exit, and a HUD."},{"id":"Pakai contoh Exit di bawah dan hubungkan signal koin ke `on_coin_collected()`.","en":"Use the Exit example below and connect the coin signal to `on_coin_collected()`."},{"id":"Uji jalur menang, kalah, dan restart. Catat setiap bug yang kamu temukan.","en":"Test the win, lose, and restart paths. Record every bug you find."}],"snippet":"extends Area2D\n\n@export var coins_total: int = 4\n\nvar coins_collected: int = 0\n\nfunc _ready() -> void:\n    body_entered.connect(_on_body_entered)\n\nfunc on_coin_collected() -> void:\n    coins_collected += 1\n\nfunc _on_body_entered(body: Node2D) -> void:\n    if body.name == \"Player\" and coins_collected >= coins_total:\n        get_tree().change_scene_to_file(\"res://win.tscn\")\n","question":{"id":"Saat membuat ulang loop ini di Godot, bug apa yang kamu temui (atau bisa terjadi) dan bagaimana kamu memperbaikinya?","en":"When recreating this loop in Godot, what bugs did you meet (or could happen) and how did you fix them?"}}}'::jsonb) on conflict (lesson_key, version) do nothing;
insert into public.survey_versions (survey_key, version, content) values ('readiness', 1, '{"key":"readiness","version":1,"title":{"id":"Survei kesiapan, minat, dan akses","en":"Readiness, interests, and access survey"},"intro":{"id":"Survei ini membantu guru menyesuaikan pelajaran dan jadwal komputer sekolah. Tidak dinilai. Jawaban \"tidak yakin\" itu wajar.","en":"This survey helps your teacher adapt lessons and school-computer scheduling. It is not graded. Answering \"not sure\" is fine."},"privacy":{"id":"Jawabanmu terlihat oleh gurumu dengan namamu. Teman sekelas tidak dapat melihatnya. Survei ini TIDAK anonim.","en":"Your teacher can see your answers with your name. Classmates cannot see them. This survey is NOT anonymous."},"minutes":7,"questions":[{"id":"R1","type":"single","required":true,"prompt":{"id":"Seberapa banyak pengalamanmu membuat game?","en":"How much experience do you have making games?"},"options":[{"value":"none","label":{"id":"Belum pernah","en":"None"}},{"value":"tutorial","label":{"id":"Pernah mengikuti tutorial","en":"Followed a tutorial"}},{"value":"small_game","label":{"id":"Pernah membuat game kecil","en":"Made a small game"}},{"value":"other","label":{"id":"Lainnya","en":"Other"}}],"followUp":{"label":{"id":"Jelaskan singkat (opsional)","en":"Short description (optional)"},"maxLength":100,"forOption":"other"}},{"id":"R2","type":"single","required":true,"prompt":{"id":"Pernahkah kamu memakai Godot?","en":"Have you used Godot before?"},"options":[{"value":"never","label":{"id":"Belum pernah","en":"Never"}},{"value":"opened","label":{"id":"Pernah membukanya","en":"Opened it"}},{"value":"tutorial","label":{"id":"Pernah menyelesaikan tutorial","en":"Completed a tutorial"}},{"value":"built","label":{"id":"Pernah membuat sesuatu","en":"Built something"}}]},{"id":"R3","type":"scale","required":true,"prompt":{"id":"Seberapa nyaman kamu membaca kode sederhana?","en":"How comfortable are you reading simple code?"},"scale":{"low":{"id":"1 = sama sekali tidak nyaman","en":"1 = not comfortable at all"},"high":{"id":"5 = sangat nyaman","en":"5 = very comfortable"},"extra":[{"value":"not_sure","label":{"id":"Tidak yakin","en":"Not sure"}}]}},{"id":"R4","type":"multi","required":false,"prompt":{"id":"Jenis game apa yang kamu minati? Pilih paling banyak tiga.","en":"Which kinds of games interest you? Choose up to three."},"options":[{"value":"puzzle","label":{"id":"Puzzle","en":"Puzzle"}},{"value":"platformer","label":{"id":"Platformer","en":"Platformer"}},{"value":"top_down","label":{"id":"Petualangan top-down","en":"Top-down adventure"}},{"value":"arcade","label":{"id":"Arcade","en":"Arcade"}},{"value":"simulation","label":{"id":"Simulasi","en":"Simulation"}},{"value":"story","label":{"id":"Cerita","en":"Story"}},{"value":"other","label":{"id":"Lainnya","en":"Other"}}],"max":3},{"id":"R5","type":"text","required":false,"prompt":{"id":"Sebutkan satu game yang kamu sukai dan satu mekanik yang kamu suka.","en":"Name one game you enjoy and one mechanic you like."},"help":{"id":"Jangan tulis nama akun atau username.","en":"Do not write account names or usernames."},"max":200},{"id":"R6","type":"single","required":true,"prompt":{"id":"Perangkat apa yang biasanya bisa kamu pakai untuk latihan sekolah?","en":"What device can you usually use for school practice?"},"options":[{"value":"personal_laptop","label":{"id":"Laptop pribadi","en":"Personal laptop"}},{"value":"shared_laptop","label":{"id":"Laptop bersama","en":"Shared laptop"}},{"value":"school_only","label":{"id":"Hanya komputer sekolah","en":"School computer only"}},{"value":"other","label":{"id":"Lainnya","en":"Other"}},{"value":"unsure","label":{"id":"Tidak yakin","en":"Unsure"}}]},{"id":"R7","type":"single","required":true,"prompt":{"id":"Apa yang terjadi saat kamu mencoba menjalankan Godot?","en":"What happens when you try running Godot?"},"options":[{"value":"not_tried","label":{"id":"Belum mencoba","en":"Haven''t tried"}},{"value":"works_well","label":{"id":"Berjalan baik","en":"Works well"}},{"value":"slow","label":{"id":"Lambat","en":"Slow"}},{"value":"crashes","label":{"id":"Crash / tertutup sendiri","en":"Crashes"}},{"value":"cannot_install","label":{"id":"Tidak bisa dipasang","en":"Cannot install"}},{"value":"unsure","label":{"id":"Tidak yakin","en":"Unsure"}}]},{"id":"R8","type":"single","required":false,"prompt":{"id":"Bisakah kamu biasanya mengakses internet untuk latihan di luar kelas?","en":"Can you usually access the internet for practice outside class?"},"options":[{"value":"reliably","label":{"id":"Ya, dengan lancar","en":"Reliably"}},{"value":"sometimes","label":{"id":"Kadang-kadang","en":"Sometimes"}},{"value":"school_only","label":{"id":"Hanya di sekolah","en":"Only at school"}},{"value":"prefer_not","label":{"id":"Memilih tidak menjawab","en":"Prefer not to answer"}}]},{"id":"R9","type":"multi","required":false,"prompt":{"id":"Kegiatan mana yang paling menarik? Pilih paling banyak dua.","en":"Which activities sound most interesting? Choose up to two."},"options":[{"value":"programming","label":{"id":"Pemrograman","en":"Programming"}},{"value":"game_design","label":{"id":"Desain game","en":"Game design"}},{"value":"art","label":{"id":"Seni/gambar","en":"Art"}},{"value":"audio","label":{"id":"Audio","en":"Audio"}},{"value":"testing","label":{"id":"Pengujian","en":"Testing"}},{"value":"organizing","label":{"id":"Mengatur tim","en":"Organizing"}}],"max":2},{"id":"R10","type":"scale","required":false,"prompt":{"id":"Seberapa percaya diri kamu bekerja dalam tim kecil?","en":"How confident are you about working in a small team?"},"scale":{"low":{"id":"1 = tidak percaya diri","en":"1 = not confident"},"high":{"id":"5 = sangat percaya diri","en":"5 = very confident"},"extra":[{"value":"prefer_not","label":{"id":"Memilih tidak menjawab","en":"Prefer not to answer"}}]}},{"id":"R11","type":"text","required":false,"prompt":{"id":"Adakah dukungan di kelas yang akan membantumu berpartisipasi?","en":"Is there a classroom support that would help you participate?"},"help":{"id":"Opsional dan hanya untuk gurumu. Jangan tuliskan detail medis; guru dapat menindaklanjuti lewat jalur sekolah.","en":"Optional and only for your teacher. Do not write medical details; your teacher can follow up through school channels."},"max":300},{"id":"R12","type":"text","required":false,"prompt":{"id":"Apa yang ingin kamu pelajari atau buat semester ini?","en":"What would you like to learn or make this semester?"},"max":300}]}'::jsonb) on conflict (survey_key, version) do nothing;
insert into public.survey_versions (survey_key, version, content) values ('project', 1, '{"key":"project","version":1,"title":{"id":"Survei minat proyek dan persiapan tim","en":"Project interests and team preparation survey"},"intro":{"id":"Ubah semangatmu menjadi ide proyek yang bisa selesai. Guru akan membentuk tim; setiap tim lalu menulis satu proposal.","en":"Turn your enthusiasm into a project idea that can be finished. Your teacher forms teams; each team then writes one proposal."},"privacy":{"id":"Jawabanmu hanya terlihat oleh guru, sampai kamu sendiri memasukkan ide yang disepakati ke proposal tim. Pilihan teman bersifat saran dan tidak dijamin.","en":"Only your teacher sees your answers, until you choose to put an agreed idea into your team proposal. Teammate preferences are suggestions and are not guaranteed."},"minutes":10,"questions":[{"id":"P1","type":"text","required":true,"prompt":{"id":"Beri judul sementara untuk ide game-mu.","en":"Give your game idea a working title."},"max":80},{"id":"P2","type":"text","required":true,"prompt":{"id":"Dalam satu kalimat, apa yang dilakukan pemain berulang kali?","en":"In one sentence, what does the player do repeatedly?"},"max":250},{"id":"P3","type":"single","required":true,"prompt":{"id":"Format game 2D pemula mana yang paling cocok?","en":"Which beginner 2D format fits best?"},"options":[{"value":"collect_exit","label":{"id":"Kumpulkan-dan-keluar","en":"Collect-and-exit"}},{"value":"dodge_survive","label":{"id":"Hindari-dan-bertahan","en":"Dodge-survive"}},{"value":"simple_puzzle","label":{"id":"Puzzle sederhana","en":"Simple puzzle"}},{"value":"top_down_explore","label":{"id":"Eksplorasi top-down","en":"Top-down exploration"}},{"value":"other","label":{"id":"Lainnya (perlu persetujuan guru)","en":"Other (requires teacher approval)"}}],"followUp":{"label":{"id":"Jelaskan format lainnya","en":"Describe the other format"},"maxLength":150,"forOption":"other"}},{"id":"P4","type":"pair","required":true,"prompt":{"id":"Apa syarat menang? Apa syarat kalah, atau mengapa tidak perlu syarat kalah?","en":"What is the win condition? What is the lose condition, or why is no lose condition appropriate?"},"pair":{"a":{"id":"Syarat menang","en":"Win condition"},"b":{"id":"Syarat kalah (atau alasan tidak ada)","en":"Lose condition (or why none)"},"maxLength":200}},{"id":"P5","type":"textlist","required":true,"prompt":{"id":"Tuliskan paling banyak tiga fitur penting.","en":"List up to three essential features."},"max":3,"min":1,"itemMaxLength":120},{"id":"P6","type":"textlist","required":false,"prompt":{"id":"Tuliskan paling banyak dua fitur tambahan (opsional).","en":"List up to two optional stretch features."},"max":2,"itemMaxLength":120},{"id":"P7","type":"multi","required":true,"prompt":{"id":"Konsep Godot apa yang akan kamu pakai?","en":"What Godot concepts will you use?"},"options":[{"value":"scenes_nodes","label":{"id":"Scene/node","en":"Scenes/nodes"}},{"value":"input","label":{"id":"Input","en":"Input"}},{"value":"collision","label":{"id":"Tabrakan","en":"Collision"}},{"value":"signals","label":{"id":"Signal","en":"Signals"}},{"value":"ui","label":{"id":"UI","en":"UI"}},{"value":"timers","label":{"id":"Timer","en":"Timers"}},{"value":"other","label":{"id":"Lainnya","en":"Other"}}],"min":1},{"id":"P8","type":"multi","required":true,"prompt":{"id":"Peran mana yang ingin kamu coba? Pilih dua dan jelaskan salah satunya.","en":"Which roles would you like to try? Choose two and explain one."},"options":[{"value":"programming","label":{"id":"Pemrograman","en":"Programming"}},{"value":"game_design","label":{"id":"Desain game","en":"Game design"}},{"value":"art","label":{"id":"Seni","en":"Art"}},{"value":"audio","label":{"id":"Audio","en":"Audio"}},{"value":"testing","label":{"id":"Pengujian","en":"Testing"}},{"value":"documentation","label":{"id":"Dokumentasi/organisasi","en":"Documentation/organizing"}}],"max":2,"min":2,"followUp":{"label":{"id":"Jelaskan salah satu pilihanmu (opsional)","en":"Explain one of your choices (optional)"},"maxLength":200}},{"id":"P9","type":"classmates","required":false,"prompt":{"id":"Dengan teman sekelas mana kamu ingin bekerja?","en":"Which classmates would you prefer to work with?"},"help":{"id":"Opsional, hanya terlihat oleh guru, dan tidak dijamin.","en":"Optional, visible only to your teacher, and not guaranteed."},"max":3},{"id":"P10","type":"single","required":true,"prompt":{"id":"Apakah kamu bersedia ditempatkan di kelompok pilihan guru?","en":"Are you open to a teacher-assigned group?"},"options":[{"value":"yes","label":{"id":"Ya","en":"Yes"}},{"value":"discuss","label":{"id":"Ingin membicarakannya secara pribadi","en":"Would like to discuss privately"}}]},{"id":"P11","type":"sessions","required":true,"prompt":{"id":"Kapan kamu bisa memakai komputer sekolah yang mampu selama sesi sekolah yang disetujui?","en":"When can you use a capable school computer during approved school sessions?"},"help":{"id":"Hanya sesi sekolah. Kami tidak menanyakan jadwal di rumah.","en":"School sessions only. We do not ask about home schedules."}},{"id":"P12","type":"single","required":true,"prompt":{"id":"Seni/audio apa yang akan kamu pakai, dan dari mana asalnya?","en":"What art/audio will you use, and where will it come from?"},"options":[{"value":"original","label":{"id":"Buatan sendiri","en":"Original"}},{"value":"teacher_pack","label":{"id":"Paket aset dari guru","en":"Teacher asset pack"}},{"value":"licensed","label":{"id":"Sumber berlisensi yang sesuai","en":"Appropriately licensed source"}}],"followUp":{"label":{"id":"Sumber (opsional)","en":"Source (optional)"},"maxLength":200}},{"id":"P13","type":"text","required":true,"prompt":{"id":"Apa yang bisa menghalangi penyelesaian, dan versi lebih sederhana apa yang tetap berhasil?","en":"What might prevent completion, and what simpler version would still work?"},"max":400},{"id":"P14","type":"text","required":false,"prompt":{"id":"Bantuan apa yang kamu butuhkan sebelum mulai?","en":"What help do you need before starting?"},"max":300}]}'::jsonb) on conflict (survey_key, version) do nothing;
